--dbo SCHEMA
--1
DO
$do$
BEGIN
    IF NOT EXISTS(
        SELECT schema_name
          FROM information_schema.schemata
          WHERE schema_name = 'dbo'
      )
    THEN
      EXECUTE 'CREATE SCHEMA dbo';
      
    END IF;
END
$do$;

--DESCRIPTION Схема для данных - dbo

drop table if exists  dbo.tcountry;

CREATE TABLE dbo.tcountry (
	"CountryID" numeric(15) NULL, -- ID
	"Name" text NULL, -- Наименование
	"Brief" text NULL, -- Сокращение
	"FundID" numeric(15) NULL, -- Денежная единица (tFund.FundID)
	"ParentID" numeric(15) NULL, -- Для населенных пунктов - страна (tCountry.CountryID)
	"Name2" text NULL, -- Наименование 2
	"CountryType" int2 NULL, -- Тип 0 Не определен 1 Страна 2 Населенный пункт 3 Регион 4 Район 5 Location Codes
	"CharCode" text NULL, -- Символьный код
	"NumCode" text NULL, -- Альтернативный код
	"COATO" text NULL, -- КОД СОАТО
	"DictionaryType" numeric(15) NULL, -- Тип справочника
	"InstrumentID" numeric(15) NULL, -- ID фин. операции
	"Settings" int4 NULL, -- 1 бит - 1 - страна участвует в соглашении по борьбе с терроризмом. 0 - не участвует
	"CodeISO" text NULL, -- код ISO
	"Alpha2" text NULL, -- код Альфа-2
	"Alpha3" text NULL, -- код Альфа-3
	"Name3" text NULL, -- Name3
	"Expires" int2 NULL, -- признак завершения актуальности.
	"ExpDate" date NULL, -- дата завершения актуальности.
	"IsCapital" int2 NULL -- признак центра (столицы)
)
;
COMMENT ON TABLE dbo.tcountry IS 'Справочник стран';

-- Column comments

COMMENT ON COLUMN dbo.tcountry."CountryID" IS 'ID';
COMMENT ON COLUMN dbo.tcountry."Name" IS 'Наименование';
COMMENT ON COLUMN dbo.tcountry."Brief" IS 'Сокращение';
COMMENT ON COLUMN dbo.tcountry."fundid" IS 'Денежная единица (tFund.FundID)';
COMMENT ON COLUMN dbo.tcountry."ParentID" IS 'Для населенных пунктов - страна (tCountry.CountryID)';
COMMENT ON COLUMN dbo.tcountry."Name2" IS 'Наименование 2';
COMMENT ON COLUMN dbo.tcountry."CountryType" IS 'Тип 0 Не определен 1 Страна 2 Населенный пункт 3 Регион 4 Район 5 Location Codes';
COMMENT ON COLUMN dbo.tcountry."CharCode" IS 'Символьный код';
COMMENT ON COLUMN dbo.tcountry."NumCode" IS 'Альтернативный код';
COMMENT ON COLUMN dbo.tcountry."COATO" IS 'КОД СОАТО';
COMMENT ON COLUMN dbo.tcountry."DictionaryType" IS 'Тип справочника';
COMMENT ON COLUMN dbo.tcountry."InstrumentID" IS 'ID фин. операции';
COMMENT ON COLUMN dbo.tcountry."Settings" IS '1 бит - 1 - страна участвует в соглашении по борьбе с терроризмом. 0 - не участвует';
COMMENT ON COLUMN dbo.tcountry."CodeISO" IS 'код ISO';
COMMENT ON COLUMN dbo.tcountry."Alpha2" IS 'код Альфа-2';
COMMENT ON COLUMN dbo.tcountry."Alpha3" IS 'код Альфа-3';
COMMENT ON COLUMN dbo.tcountry."Name3" IS 'Name3';
COMMENT ON COLUMN dbo.tcountry."Expires" IS 'признак завершения актуальности.';
COMMENT ON COLUMN dbo.tcountry."ExpDate" IS 'дата завершения актуальности.';
COMMENT ON COLUMN dbo.tcountry."IsCapital" IS 'признак центра (столицы)';

